// <auto-generated />
using NUnit.Framework;
using UnityEngine;
using System.Collections.Generic;
using System.Linq;
namespace Spinnenspiel.Tests
{
    [TestFixture]
    public class JunglePlantFactoryTests
    {
        [Test]
        public void GiantLeaf_HasGeometry()
        {
            var mesh = Spinnenspiel.JunglePlantFactory.GiantLeafPlant(1);
            Assert.That(mesh, Is.Not.Null);
            Assert.That(mesh.vertexCount, Is.GreaterThan(100));
            Assert.That(mesh.triangles.Length % 3, Is.EqualTo(0));
            Assert.That(mesh.bounds.size.y >= 0.3f && mesh.bounds.size.y <= 1.8f);
            Assert.That(mesh.bounds.size.x >= 0.3f && mesh.bounds.size.x <= 2.5f);
        }

        [Test]
        public void GiantLeaf_Deterministic()
        {
            var mesh1 = Spinnenspiel.JunglePlantFactory.GiantLeafPlant(42);
            var mesh2 = Spinnenspiel.JunglePlantFactory.GiantLeafPlant(42);
            Assert.That(mesh1.vertexCount, Is.EqualTo(mesh2.vertexCount));
            for (int i = 0; i < 10; i++)
            {
                Assert.That(mesh1.vertices[i].x, Is.EqualTo(mesh2.vertices[i].x), "x");
                Assert.That(mesh1.vertices[i].y, Is.EqualTo(mesh2.vertices[i].y), "y");
                Assert.That(mesh1.vertices[i].z, Is.EqualTo(mesh2.vertices[i].z), "z");
            }
        }

        [Test]
        public void GiantLeaf_VariantsDiffer()
        {
            var meshes = new Dictionary<int, Mesh>();
            for (int seed = 1; seed <= 6; seed++)
            {
                var mesh = Spinnenspiel.JunglePlantFactory.GiantLeafPlant(seed);
                meshes[seed] = mesh;
            }
            
            var pairs = new List<(int s1, int s2)>();
            for (int i = 0; i < 5; i++)
            {
                for (int j = i + 1; j < 6; j++)
                {
                    pairs.Add((i + 1, j + 1));
                }
            }
            
            int differing = 0;
            foreach (var pair in pairs)
            {
                var m1 = meshes[pair.s1];
                var m2 = meshes[pair.s2];
                var diff = m1.vertexCount != m2.vertexCount || 
                          Mathf.Abs(m1.bounds.size.x - m2.bounds.size.x) > 0.05f ||
                          Mathf.Abs(m1.bounds.size.y - m2.bounds.size.y) > 0.05f;
                if (diff) differing++;
            }
            
            Assert.That(differing, Is.GreaterThanOrEqualTo(4));
        }

        [Test]
        public void Liana_HasGeometry()
        {
            var mesh = JunglePlantFactory.HangingLiana(1);
            Assert.That(mesh, Is.Not.Null);
            Assert.That(mesh.vertexCount > 50);
            Assert.That(mesh.triangles.Length % 3 == 0);
            Assert.That(mesh.bounds.size.y >= 2.0f && mesh.bounds.size.y <= 4.5f);
            Assert.That(mesh.bounds.size.x < 1.2f);
            Assert.That(mesh.bounds.size.z < 1.2f);
        }

        [Test]
        public void Liana_Deterministic()
        {
            var a = JunglePlantFactory.HangingLiana(42);
            var b = JunglePlantFactory.HangingLiana(42);
            Assert.That(a.vertexCount == b.vertexCount);
            var va = a.vertices;
            var vb = b.vertices;
            for (int i = 0; i < 10; i++)
            {
                Assert.That(Mathf.Approximately(va[i].x, vb[i].x));
                Assert.That(Mathf.Approximately(va[i].y, vb[i].y));
                Assert.That(Mathf.Approximately(va[i].z, vb[i].z));
            }
        }

        [Test]
        public void Liana_VariantsDiffer()
        {
            var meshes = new List<Mesh>();
            for (int s = 1; s <= 6; s++)
                meshes.Add(JunglePlantFactory.HangingLiana(s));
            int differing = 0;
            for (int i = 0; i < 6; i++)
            {
                for (int j = i + 1; j < 6; j++)
                {
                    var m1 = meshes[i];
                    var m2 = meshes[j];
                    if (m1.vertexCount != m2.vertexCount ||
                        Mathf.Abs(m1.bounds.size.y - m2.bounds.size.y) > 0.05f ||
                        Mathf.Abs(m1.bounds.size.x - m2.bounds.size.x) > 0.05f)
                        differing++;
                }
            }
            Assert.That(differing >= 4);
        }

        // KLEE2: Klee-Optik — gewoelbte Teilblaetter statt flacher Platten.
        [Test]
        public void Clover_TriCountAndCurvature()
        {
            var mesh = Spinnenspiel.CloverFactory.Clover(7);
            int tris = mesh.triangles.Length / 3;
            UnityEngine.Debug.Log(string.Format("[KLEE2] Dreiecke je Kleepflanze={0} -> Kriterium >= 20 -> {1}",
                tris, tris >= 20 ? "OK" : "NOK"));
            Assert.That(tris, Is.GreaterThanOrEqualTo(20));

            // Voelbung: die Blattverterex liegen NICHT in einer Ebene. Naechste-Nachbarn
            // (Dreiecke teilen Positionen nicht, da nicht indexiert) ueber Normalen pruefen:
            // die Spanne der y-Normalen muss deutlich > 0 sein (flache Platte = gleiche Normale).
            var normals = mesh.normals;
            float nmin = 1f, nmax = -1f;
            for (int i = 0; i < normals.Length; i++)
            {
                if (normals[i].y < nmin) nmin = normals[i].y;
                if (normals[i].y > nmax) nmax = normals[i].y;
            }
            float span = nmax - nmin;
            UnityEngine.Debug.Log(string.Format("[KLEE2] Normalen-y-Spanne={0:F3} -> Kriterium >= 0.15 (Voelbung) -> {1}",
                span, span >= 0.15f ? "OK" : "NOK"));
            Assert.That(span, Is.GreaterThanOrEqualTo(0.15f));

            // Blattbreite in Mesh-Einheit: L max 0.7 -> Breite <= 2*0.7; mit scale 8..13 cm
            // ergibt das Blaetter bis ~9 cm (Kriterium im Welt-Test KleeTests).
            Assert.That(mesh.bounds.size.x, Is.LessThanOrEqualTo(1.5f));
        }

        [Test]
        public void Clover_Deterministic()
        {
            var a = Spinnenspiel.CloverFactory.Clover(3);
            var b = Spinnenspiel.CloverFactory.Clover(3);
            Assert.That(a.vertexCount, Is.EqualTo(b.vertexCount));
            var va = a.vertices; var vb = b.vertices;
            for (int i = 0; i < va.Length; i++)
                Assert.That(Mathf.Approximately(va[i].x, vb[i].x) &&
                            Mathf.Approximately(va[i].y, vb[i].y) &&
                            Mathf.Approximately(va[i].z, vb[i].z));
        }
    }
